<a class="catalog-product-card reveal" href="<?=e(cms_url('/products/'.$product['slug'].'/'))?>"><?php if($product['image_id']):?><div class="catalog-product-media"><?=media_img($product['image_id'],$product['title'])?></div><?php else:?><div class="catalog-product-media catalog-product-placeholder"><i class="fa-solid fa-box"></i></div><?php endif?><?php if($product['badge']):?><span class="product-detail-badge"><?=e($product['badge'])?></span><?php endif?><h3><?=e($product['title'])?></h3><?php foreach(['brand','category','subcategory'] as $key):if(!empty($product[$key.'_name'])):?><p><?=text($key)?>: <?=e($product[$key.'_name'])?></p><?php endif;endforeach?></a>
